SELECT n.id, n.user_id, u.username, n.title, n.note_type, n.location_or_url, n.summary, n.cover_image, n.view_count as viewCount, n.is_pinned as isPinned, n.is_public as isPublic, n.created_at, n.updated_at FROM t_note_item n LEFT JOIN t_user u ON n.user_id = u.id WHERE n.user_id = #{userId} AND n.is_deleted = 0 AND (n.is_public = 1 OR (#{currentUserId} IS NOT NULL AND #{currentUserId} = #{userId}))
AND n.note_type = #{noteType}
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR n.location_or_url LIKE CONCAT('%', #{keyword}, '%') OR n.summary LIKE CONCAT('%', #{keyword}, '%'))
AND n.created_at >= #{startDate}
AND n.created_at < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
ORDER BY n.is_pinned DESC, n.updated_at DESC

SELECT n.id, n.user_id, u.username, n.title, n.note_type, n.location_or_url, n.summary, n.cover_image, n.view_count as viewCount, n.is_pinned as isPinned, n.is_public as isPublic, n.is_deleted, n.created_at, n.updated_at, (SELECT COUNT(*) FROM t_note_favorite f WHERE f.note_id = n.id) as favoriteCount FROM t_note_item n LEFT JOIN t_user u ON n.user_id = u.id
AND n.note_type = #{noteType}
AND n.is_public = #{isPublic}
AND (n.title LIKE CONCAT('%', #{keyword}, '%') OR u.username LIKE CONCAT('%', #{keyword}, '%') OR n.summary LIKE CONCAT('%', #{keyword}, '%'))
AND n.is_deleted = #{isDeleted}
ORDER BY n.is_pinned DESC, n.updated_at DESC
